const s=t=>{if(!t)return"Date non définie";try{const e=new Date(t);if(isNaN(e.getTime()))return"Date invalide";const r=["Dimanche","Lundi","Mardi","Mercredi","Jeudi","Vendredi","Samedi"],n=["Janvier","Février","Mars","Avril","Mai","Juin","Juillet","Août","Septembre","Octobre","Novembre","Décembre"],a=r[e.getDay()],o=e.getDate(),i=n[e.getMonth()],c=e.getFullYear();return`${a} ${o} ${i} ${c}`}catch(e){return console.error("Erreur formatage date:",e),"Date invalide"}},u=(t,e)=>{const r=s(t);if(e){const n=e.replace(":","h");return`${r} à ${n}`}return r};export{s as a,u as f};
